with flattened_attrs as (select id, plan, effective_from, currency, tier_limits, discounts, slice(tier_limits, 1, 2) as first_two_limits, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, element_at(tier_prices, 1) as entry_price, array_min(tier_prices) as lowest_price from price_tiers) select *, first_value(lowest_price) ignore nulls over w_hist as first_known_lowest_price, dense_rank() over w_recent as lowest_price_dense_rank, sum(lowest_price) over (partition by currency order by entry_price, id rows between unbounded preceding and current row) as running_lowest_price from flattened_attrs window w_hist as (partition by currency order by lowest_price, id rows between unbounded preceding and current row), w_recent as (partition by currency order by lowest_price desc nulls last)
